import React, { FormEvent } from 'react';

import { getGeoRegionsAsync, IGeoRegion } from '@apps/Routes/@services/geo.services';
import PohAlert from '@ui-kit/Alert';
import PohInput from '@ui-kit/Input';
import InputTypes from '@ui-kit/Input/InputTypes';
import PohLoader, { LoaderSize } from '@ui-kit/Loader';

import { IAddObstacleConstraints } from './modalHelper';
import {
  obstacleCategoryNameResource,
  obstacleTypeNameResource,
} from '../../@resources/obstacles.resource';
import { addObstacleAsync, updateObstacleAsync } from '../../@services/obstacles.service';
import { IObstacle, ObstacleCategory, ObstacleType } from '../../@types/obstacles.types';

interface IObstacleModalProps {
  onAdd?: (selected: IObstacle) => void;
  onEdit?: (selected: IObstacle) => void;
  constraints?: IAddObstacleConstraints;
  onCancel: () => void;
  data: IObstacle;
}

const ObstacleModal: React.FC<IObstacleModalProps> = ({ data, onAdd, onEdit, constraints }) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();
  const [isSaving, setIsSaving] = React.useState(false);
  const [_savingErr, setSavingErr] = React.useState<Error>();
  const [geoRegions, setGeoRegions] = React.useState<IGeoRegion[]>([]);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        setGeoRegions(await getGeoRegionsAsync());
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, []);

  if (isLoading) {
    return <PohLoader />;
  }

  if (err) {
    return <PohAlert>{err.message}</PohAlert>;
  }

  interface CustomElements extends HTMLFormControlsCollection {
    region: HTMLSelectElement;
    type: HTMLSelectElement;
    category: HTMLSelectElement;
    name: HTMLInputElement;
    lat: HTMLInputElement;
    lon: HTMLInputElement;
    alt: HTMLInputElement;
    comment: HTMLInputElement;
    description: HTMLInputElement;
    link: HTMLInputElement;
  }

  interface CustomForm extends HTMLFormElement {
    readonly elements: CustomElements;
  }

  const handleSubmit = async (e: FormEvent<CustomForm>) => {
    e.preventDefault();
    const { elements } = e.currentTarget;

    const region = elements.region.value;
    const type = elements.type.value;
    const category = elements.category.value;
    const name = elements.name.value;
    const lat = elements.lat.value;
    const lon = elements.lon.value;
    const alt = elements.alt.value;
    const comment = elements.comment.value;
    const description = elements.description.value;
    const link = elements.link.value;

    const updatedObstacle: IObstacle = {
      ...data,
      name,
      description,
      coordinates: [+lat, +lon],
      altitude: +alt,
      link: link,
      comment,
      type: type as ObstacleType,
      category: category as ObstacleCategory,
      region: geoRegions.find((r) => r.id === +region) ?? null,
    };

    try {
      setIsSaving(true);
      if (updatedObstacle.id > 0) {
        const edited = await updateObstacleAsync(updatedObstacle);
        onEdit?.(edited);
      } else {
        const added = await addObstacleAsync(updatedObstacle);
        onAdd?.(added);
      }
    } catch (errInCatch) {
      setSavingErr(errInCatch as Error);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="d-flex flex-column" style={{ gap: 12 }}>
      <div className="form-group row">
        <label className="col-form-label col-sm-2">Регион</label>
        <div className="col-sm-10">
          <select
            className="form-control"
            name="region"
            required
            defaultValue={data.region?.id}
            disabled={isSaving}
          >
            {geoRegions.map((region) => (
              <option key={region.id} value={region.id}>
                {region.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="form-group row">
        <label className="col-form-label col-sm-2">Тип/Категория</label>
        <div className="col-sm-10">
          <select
            className="form-control d-inline-block w-auto"
            name="type"
            required
            defaultValue={constraints?.type ?? data.type}
            disabled={!!constraints?.type || isSaving}
          >
            {Object.entries(obstacleTypeNameResource).map(([k, v]) => (
              <option key={k} value={k}>
                {v}
              </option>
            ))}
          </select>
          &nbsp;
          <select
            className="form-control d-inline-block w-auto"
            name="category"
            required
            defaultValue={data.category}
            disabled={isSaving}
          >
            {Object.entries(obstacleCategoryNameResource).map(([k, v]) => (
              <option key={k} value={k}>
                {v}
              </option>
            ))}
          </select>
        </div>
      </div>

      <PohInput
        horizontal
        name="name"
        defaultValue={data.name}
        label="Название*"
        placeholder="Название локального препятствия или POI"
        required
        autoFocus
        disabled={isSaving}
      />
      <div className="form-group row">
        <label className="col-form-label col-sm-2">Координаты</label>
        <div className="col-sm-10 row">
          <div className="col-sm-4">
            <PohInput
              name="lat"
              message="Широта (lat)"
              defaultValue={data.id > 0 ? data.coordinates[0] : ''}
              placeholder="Широта*"
              required
              type={InputTypes.number}
              min={-90}
              max={90}
              step={0.000001}
              maxLength={9}
              disabled={isSaving}
            />
          </div>
          <div className="col-sm-4">
            <PohInput
              name="lon"
              message="Долгота (lon)"
              defaultValue={data.id > 0 ? data.coordinates[1] : ''}
              placeholder="Долгота*"
              required
              type={InputTypes.number}
              min={-90}
              max={90}
              step={0.000001}
              maxLength={9}
              disabled={isSaving}
            />
          </div>
          <div className="col-sm-4">
            <PohInput
              name="alt"
              message="Высота (м.н.у.м)"
              placeholder="Высота*"
              defaultValue={data.id > 0 ? data.altitude : ''}
              required
              type={InputTypes.number}
              min={-1000}
              max={9000}
              step={1}
              maxLength={4}
              disabled={isSaving}
            />
          </div>
        </div>
      </div>

      <PohInput
        horizontal
        name="comment"
        defaultValue={data.comment}
        label="Комментарий"
        placeholder="Альтернативные название, или изменение категории зимой"
        disabled={isSaving}
        maxLength={256}
      />
      <PohInput
        horizontal
        name="description"
        defaultValue={data.description}
        label="Описание"
        maxLength={512}
        type={InputTypes.textarea}
        disabled={isSaving}
        placeholder="Описание локального препятствия или POI"
      />
      <PohInput
        horizontal
        name="link"
        defaultValue={data.link}
        type={InputTypes.url}
        label="Ссылка"
        placeholder="Ссылка на источник"
        disabled={isSaving}
      />

      <footer className="text-end mb-n3 mx-n3 px-3 border-top">
        <button type="submit" disabled={isSaving} className="btn btn-primary mt-3 ms-auto">
          {isSaving ? (
            <PohLoader size={LoaderSize.Small} />
          ) : (
            <>{data.id > 0 ? 'Сохранить' : 'Добавить'}</>
          )}
        </button>
      </footer>
    </form>
  );
};

export default ObstacleModal;
